#pragma once
#include "rinkfit/joint_packet.hpp"
#include "rinkfit/joint_path_generation_v1.hpp"
#include <ceres/problem.h>
#include <ceres/jet.h>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <limits>
namespace rinkfit {
inline bool joint_shape_vertex_path_v1(const EventPath&p){return p.kind==6&&!p.vertex_blocks.empty();}
inline bool joint_has_shape_vertex_paths_v1(const JointEventModel&m){for(const auto&material:m.materials)for(const auto&p:material.paths)if(joint_shape_vertex_path_v1(p))return true;return false;}
inline int joint_shape_segment_count_v1(const EventPath&p){if(!joint_shape_vertex_path_v1(p))return 0;const int n=int(p.vertex_blocks.size());return n==1?1:(p.closed?n:n-1);}
inline bool joint_shape_cell_contains_v1(const EventPath&p,int cell,double s){const int n=joint_shape_segment_count_v1(p);return n>0&&cell>=0&&cell<n&&std::isfinite(s)&&s>=double(cell)/n&&s<=double(cell+1)/n;}
inline int joint_shape_segment_from_station_v1(const EventPath&p,double s){const int n=joint_shape_segment_count_v1(p);if(n<=0||!std::isfinite(s)||s<0||s>1)return -1;int k=std::min(n-1,int(std::floor(s*n)));if(k>0&&s<double(k)/n)--k;if(k+1<n&&s>double(k+1)/n)++k;return joint_shape_cell_contains_v1(p,k,s)?k:-1;}
inline const EventPath*joint_row_shape_vertex_path_v1(const JointEventModel&m,const JointObservation&r){if(r.material<0||std::size_t(r.material)>=m.materials.size()||r.path<0||std::size_t(r.path)>=m.materials[r.material].paths.size())return nullptr;const auto&p=m.materials[r.material].paths[r.path];return joint_shape_vertex_path_v1(p)?&p:nullptr;}
inline std::array<double,2>joint_shape_cell_station_interval_v1(const JointEventModel&m,const JointObservation&r,double station,int selected_cell=-2){const int cell=selected_cell==-2?r.numerical_shape_segment:selected_cell;const auto*p=joint_row_shape_vertex_path_v1(m,r);if(!p||!joint_shape_cell_contains_v1(*p,cell,station))throw std::runtime_error("local shape station does not belong to its saved numerical cell");const int n=joint_shape_segment_count_v1(*p);const double lo=double(cell)/n,hi=double(cell+1)/n;
 auto intervals=r.station_intervals(m,r.path);std::sort(intervals.begin(),intervals.end());std::vector<std::array<double,2>>merged;for(auto v:intervals){if(v[0]>v[1])throw std::runtime_error("invalid original source station interval");if(!merged.empty()&&v[0]<=merged.back()[1])merged.back()[1]=std::max(merged.back()[1],v[1]);else merged.push_back(v);}for(const auto&v:merged){const auto a=std::max(lo,v[0]),b=std::min(hi,v[1]);if(a<=station&&station<=b)return {a,b};}throw std::runtime_error("local shape cell has no source-admitted interval containing actual station");
}
inline int joint_shape_cell_inward_direction_v1(const JointEventModel&m,const JointObservation&r,double station,int cell){const auto range=joint_shape_cell_station_interval_v1(m,r,station,cell);if(!(range[1]>range[0]))return 0;if(station==range[0])return 1;if(station==range[1])return -1;return 0;}
inline int joint_shape_vertex_at_cell_endpoint_v1(const EventPath&p,int cell,double station){if(!joint_shape_cell_contains_v1(p,cell,station))return -1;const int count=joint_shape_segment_count_v1(p),vertices=int(p.vertex_blocks.size());if(station==double(cell)/count)return cell%vertices;if(station==double(cell+1)/count)return (cell+1)%vertices;return -1;}
inline bool joint_shape_same_vertex_chart_change_v1(const EventPath&p,int old_cell,double old_station,int cell,double station){if(cell==old_cell)return false;const int a=joint_shape_vertex_at_cell_endpoint_v1(p,old_cell,old_station),b=joint_shape_vertex_at_cell_endpoint_v1(p,cell,station);return a>=0&&a==b;}
inline std::vector<std::pair<int,double>> joint_shape_neighbor_cells_v1(const EventPath&p,int cell,double station){std::vector<std::pair<int,double>>neighbors;const int n=joint_shape_segment_count_v1(p);if(!joint_shape_cell_contains_v1(p,cell,station))return neighbors;if(station==double(cell)/n){if(cell>0)neighbors.push_back({cell-1,station});else if(p.closed)neighbors.push_back({n-1,1.});}if(station==double(cell+1)/n){if(cell+1<n)neighbors.push_back({cell+1,station});else if(p.closed)neighbors.push_back({0,0.});}return neighbors;}
struct JointShapeInwardSlopeV1 {bool valid=false,descent=false;int direction=0;double gradient=0,tolerance=0;};
inline JointShapeInwardSlopeV1 joint_shape_inward_pixel_slope_v1(const JointEventModel&m,const JointObservation&r,double station,int cell,double fixed_row){
 JointShapeInwardSlopeV1 result;const auto*shape=joint_row_shape_vertex_path_v1(m,r);if(!shape||!r.station_allowed(m,r.path,station)||!joint_shape_cell_contains_v1(*shape,cell,station))return result;result.direction=joint_shape_cell_inward_direction_v1(m,r,station,cell);if(!result.direction)return result;
 const auto l=m.layout(m.shot_map.at(r.shot_id),r.material,r.path,r.pts,r.width_block,r.width_sign,station,cell);using J=ceres::Jet<double,1>;std::vector<std::vector<J>>values;std::vector<const J*>p;for(int bi:l.block_ids){values.emplace_back();for(double x:m.blocks.at(bi).values)values.back().emplace_back(x);}for(const auto&v:values)p.push_back(v.data());J s(station);s.v[0]=1.;const auto predicted=m.predict_for_al(l,s,J(fixed_row),p.data());if(!predicted.arithmetic_valid||predicted.physical_status!=DomainStatus::kValid)return result;double e2=0,j2=0;for(int k=0;k<2;++k){const double e=predicted.uv[k].a-r.uv[k],j=predicted.uv[k].v[0];result.gradient+=e*j;e2+=e*e;j2+=j*j;}result.valid=std::isfinite(result.gradient)&&std::isfinite(e2)&&std::isfinite(j2);result.tolerance=128*std::numeric_limits<double>::epsilon()*std::max(1.,std::sqrt(e2*j2));result.descent=result.valid&&result.direction*result.gradient < -result.tolerance;return result;
}
// Bind numerical charts only. Preserve all raw pixels, identities and primal
// station/row/alpha values, including inactive historical failures.
template<class Builder>inline eventio::Json initialize_joint_shape_cells_v1(Builder&b){std::vector<int>cells;cells.reserve(b.core.packet.rows.size());std::size_t local=0,active=0,initialized=0,preserved=0,failed=0;for(std::size_t i=0;i<b.core.packet.rows.size();++i){const auto&r=b.core.packet.rows[i];const auto*p=joint_row_shape_vertex_path_v1(b.core.model,r);int cell=-1;if(p){++local;active+=r.active;const double station=b.core.station.at(i);cell=r.numerical_shape_segment;if(cell<0){cell=joint_shape_segment_from_station_v1(*p,station);initialized+=cell>=0;}else ++preserved;if(cell>=0&&!joint_shape_cell_contains_v1(*p,cell,station))throw std::runtime_error("saved shape cell is incompatible with complete raw station");if(r.active&&(cell<0||!r.station_allowed(b.core.model,r.path,station)))throw std::runtime_error("active local shape has invalid original finite station");failed+=cell<0;}else if(r.numerical_shape_segment>=0)throw std::runtime_error("numerical shape cell attached to another primitive");cells.push_back(cell);}advance_joint_path_generation_v1(b.core.packet);for(std::size_t i=0;i<cells.size();++i)b.core.packet.rows[i].numerical_shape_segment=cells[i];return {{"schema","rinkfit.local_static_shape_cell_binding.v1"},{"all_raw_rows",cells.size()},{"local_shape_raw_rows",local},{"active_local_shape_rows",active},{"new_numeric_cells",initialized},{"saved_one_sided_cells_preserved",preserved},{"inactive_invalid_stations_retained",failed},{"station_row_alpha_path_or_source_values_changed",false},{"numeric_cell_is_source_permission",false}};}
template<class Builder>inline eventio::Json install_joint_shape_cell_station_bounds_v1(Builder&b,ceres::Problem&p){std::size_t rows=0,lower=0,upper=0;for(std::size_t i=0;i<b.core.packet.rows.size();++i){const auto&r=b.core.packet.rows[i];if(!r.active||r.kind==1||!joint_row_shape_vertex_path_v1(b.core.model,r))continue;auto*s=&b.core.station[i];if(!p.HasParameterBlock(s))throw std::runtime_error("local shape row omitted its original station variable");if(p.GetManifold(s))throw std::runtime_error("local shape cell cannot use a cross-cell station manifold");const auto interval=joint_shape_cell_station_interval_v1(b.core.model,r,*s);p.SetParameterLowerBound(s,0,interval[0]);p.SetParameterUpperBound(s,0,interval[1]);++rows;lower+=*s==interval[0];upper+=*s==interval[1];}return {{"schema","rinkfit.actual_local_shape_station_cell_bounds.v1"},{"rows",rows},{"at_cell_or_source_lower_bound",lower},{"at_cell_or_source_upper_bound",upper},{"original_source_domain_unchanged",true},{"other_legal_cells_require_accepted_graph_rebind",true},{"global_cell_optimality_certified",false}};}
inline std::string joint_shape_cells_RLE_i32_v1(const JointPacket&p){std::string out;for(std::size_t i=0;i<p.rows.size();){std::size_t j=i+1;while(j<p.rows.size()&&p.rows[j].numerical_shape_segment==p.rows[i].numerical_shape_segment)++j;out+=std::to_string(j-i)+":"+std::to_string(p.rows[i].numerical_shape_segment)+";";i=j;}return out;}
inline void restore_joint_shape_cells_RLE_i32_v1(const std::string&encoded,JointPacket&p,const JointEventModel&m,const std::vector<double>&station){if(station.size()!=p.rows.size())throw std::runtime_error("shape cell checkpoint raw station denominator differs");std::vector<int>cells;cells.reserve(p.rows.size());std::size_t pos=0;while(pos<encoded.size()){const auto colon=encoded.find(':',pos),end=encoded.find(';',pos);if(colon==std::string::npos||end==std::string::npos||colon>=end)throw std::runtime_error("invalid local shape cell checkpoint RLE");std::size_t used=0;const auto count=std::stoull(encoded.substr(pos,colon-pos),&used);if(!count||used!=colon-pos||count>p.rows.size()-cells.size())throw std::runtime_error("local shape cell checkpoint run count");const auto value=std::stoll(encoded.substr(colon+1,end-colon-1),&used);if(used!=end-colon-1||value< -1||value>std::numeric_limits<int>::max())throw std::runtime_error("local shape cell checkpoint value");for(std::size_t k=0;k<count;++k)cells.push_back(int(value));pos=end+1;}if(cells.size()!=p.rows.size())throw std::runtime_error("incomplete local shape cell checkpoint");
 for(std::size_t i=0;i<cells.size();++i){const auto&r=p.rows[i];const auto*path=joint_row_shape_vertex_path_v1(m,r);if(!path){if(cells[i]!=-1)throw std::runtime_error("checkpoint shape cell changes primitive identity");continue;}if(cells[i]>=0&&!joint_shape_cell_contains_v1(*path,cells[i],station[i]))throw std::runtime_error("checkpoint local shape cell differs from complete station");if(r.active&&(cells[i]<0||!r.station_allowed(m,r.path,station[i])))throw std::runtime_error("checkpoint omitted active shape cell or original finite station");}advance_joint_path_generation_v1(p);for(std::size_t i=0;i<cells.size();++i)p.rows[i].numerical_shape_segment=cells[i];
}
}
